from fastapi import FastAPI, HTTPException
from pymongo.errors import PyMongoError
from .integrations import auth_router, object_router
from .database import database, get_session, lifespan as database_lifespan

@asynccontextmanager
async def lifespan(application: FastAPI) -> AsyncIterator[None]:
    """Lifespan."""
    async with database_lifespan(application):
        try:
            yield
        finally:
            close_integrations()


app = FastAPI(lifespan=lifespan)
app.include_router(auth_router)
app.include_router(object_router)
app.include_router(create_router(get_session))

@app.get("/healthz")
async def healthz() -> dict[str, str]:
    """Healthz."""
    try:
        await database.command("ping")
    except PyMongoError as exc:
        raise HTTPException(status_code=503, detail="database unavailable") from exc
    return {"status": "ok"}
JSON_VALUE: TypeAdapter[JsonValue] = TypeAdapter(JsonValue)


def _has_nonfinite(value: JsonValue) -> bool:


    """ has nonfinite."""
    if isinstance(value, float):
        return not isfinite(value)
    if isinstance(value, list):
        return any(_has_nonfinite(item) for item in value)
    if isinstance(value, dict):
        return any(_has_nonfinite(item) for item in value.values())
    return False


@app.exception_handler(RequestValidationError)
async def validation_error(request: Request, error: RequestValidationError) -> Response:
    """Validation error."""
    try:
        body = JSON_VALUE.validate_python(error.body, strict=True)
    except ValidationError:
        return await request_validation_exception_handler(request, error)
    if _has_nonfinite(body):
        return JSONResponse(status_code=422, content={"detail": [{
            "type": "finite_number", "loc": ["body"],
            "msg": "Input must contain finite JSON numbers",
        }]})
    return await request_validation_exception_handler(request, error)
